import sys

input = sys.stdin.read
data = input().split()

def read_ints():
    return list(map(int, data.pop(0).split()))

t = read_ints()[0]

results = []

for _ in range(t):
    n, x = read_ints()
    blows = [read_ints() for _ in range(n)]

    dp = [-1] * (x + 1)
    dp[0] = 0

    for i in range(1, x + 1):
        min_blows = float('inf')
        for d, h in blows:
            if i >= d:
                new_heads = max(0, i - d + h)
                if dp[new_heads] != -1:
                    min_blows = min(min_blows, dp[new_heads])
        if min_blows != float('inf'):
            dp[i] = min_blows + 1

    results.append(dp[x])

for result in results:
    print(result)
