from sys import stdin, stdout

def min_blowouts(n, x, d, h):
    d.sort()
    h.sort(reverse=True)

    i = j = 0
    while i < n and j < n and x > 0:
        if d[i] <= x:
            x -= d[i]
            x += h[j]
            j += 1
            if x <= 0:
                return 1
        else:
            i += 1

    return -1 if x > 0 else 1 + max(0, (x - 1) // d[-1])

def solve():
    t = int(stdin.readline().strip())
    results = []
    for _ in range(t):
        n, x = map(int, stdin.readline().strip().split())
        d = [int(x) for x in stdin.readline().strip().split()]
        h = [int(x) for x in stdin.readline().strip().split()]
        result = min_blowouts(n, x, d, h)
        results.append(result)
    for result in results:
        stdout.write(f"{result}\n")

if __name__ == "__main__":
    solve()
